select t.n, t.slug, t.field, t.rows_matched, t.text_ok
from (values
  (1, 'akua-mediterranean', 'why_its_here', (select count(*)::int from venues where slug = 'akua-mediterranean' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '3e746cb25400ddb9a0e50f33fd5e0b75'), md5('A beachfront Mediterranean bar and restaurant on Jimbaran Beach, at Pemelisan Agung No. 27, formerly AKUA de Bilbao. The kitchen does Spanish tapas, mezze, handmade pastas, sourdough pizzas and grilled seafood from the bay, and the open terrace upstairs faces the sunset.') = 'c8cb493ce9bdd3896673d1b328505ecb'),
  (2, 'akua-mediterranean', 'best_for', (select count(*)::int from venues where slug = 'akua-mediterranean' and status = 'active' and publication_status = 'published' and md5(best_for) = '0523082b01d57503423bf81568574a26'), md5('Sunset drinks and shared plates by the sea, or a long, social seafood lunch with a group') = '993e4241b5f780651676cb8d9612539e'),
  (3, 'arkipela-spa-at-mo-venpick-jimbaran-jimbaran', 'best_for', (select count(*)::int from venues where slug = 'arkipela-spa-at-mo-venpick-jimbaran-jimbaran' and status = 'active' and publication_status = 'published' and md5(best_for) = '016ae0927c8831ba4294fda2d45db145'), md5(U&'A polished resort spa treatment near Samasta''s shops and caf\00E9s') = '5cea144d2be2fea389fefde359cf65f6'),
  (4, 'arwana', 'why_its_here', (select count(*)::int from venues where slug = 'arwana' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '4e0d07bc59791e08ec8f53300d3ce684'), md5('The beachfront grill restaurant at The Laguna, a Luxury Collection Resort & Spa in Nusa Dua. Fresh seafood and dry-aged meats are cooked over Basque-style wood grills, alongside a Balinese menu. Tables are on a terrace beside the beach and the lagoon pools.') = '714700d83295d5dc231ca32a56454e04'),
  (5, 'arwana', 'best_for', (select count(*)::int from venues where slug = 'arwana' and status = 'active' and publication_status = 'published' and md5(best_for) = '3dfc9d736ceacce94fb13dd085be1d12'), md5('A seaside grill lunch or dinner with an ocean view, or the Sunday brunch, for resort guests and couples') = 'a4bee22f2853fbbc73911549557d1146'),
  (6, 'ayana-fitness-centre', 'why_its_here', (select count(*)::int from venues where slug = 'ayana-fitness-centre' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '79f4e048f7b8b001a4081127e3f689fa'), md5('The 24-hour gym on the AYANA estate above Jimbaran Bay. Steam and sauna rooms, a jacuzzi grotto, a cold plunge pool and an aerobics and yoga studio share its wellness complex. Personal trainers can be booked, and the grounds have lawn tennis and table tennis.') = '78d7670e5800618552bffea2a1041f9b'),
  (7, 'ayana-fitness-centre', 'best_for', (select count(*)::int from venues where slug = 'ayana-fitness-centre' and status = 'active' and publication_status = 'published' and md5(best_for) = 'd6d03997841ed764618adde29498881b'), md5('Guests on the AYANA estate who want a round-the-clock gym with sauna and cold plunge, and racquet sports on the same site') = '1213d222e2d213e9230b66d752a28cb8'),
  (8, 'azure-beach-restaurant', 'why_its_here', (select count(*)::int from venues where slug = 'azure-beach-restaurant' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'b7948740bb0e664f2bcb85ff2196c3d2'), md5('A beachfront Mediterranean restaurant with a pool on Kelan Beach, near Jimbaran. The seafood is locally sourced, and the chef is Frederic Boulay. There are daybeds, direct beach access and no cover charge.') = '00ef3cea144784b4ea22f89fb00ad541'),
  (9, 'azure-beach-restaurant', 'best_for', (select count(*)::int from venues where slug = 'azure-beach-restaurant' and status = 'active' and publication_status = 'published' and md5(best_for) = '8e9a7e12f20e4eb87922f36e93868293'), md5('Sunset seafood and an unhurried afternoon by the pool, or a last stop before an airport departure') = '8e7b1ee427954d4ba66b0d86e97e98b8'),
  (10, 'bali-barber-jimbaran', 'why_its_here', (select count(*)::int from venues where slug = 'bali-barber-jimbaran' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'c7ac49345bc51ef872795c56417742cc'), md5('Bali Barber''s Jimbaran branch, part of the men''s grooming chain. You can walk in for a cut, a beard tidy or a hot-towel shave near the bay.') = '0f9ce68cd10134d5a9e83fe6c3ed7a53'),
  (11, 'bali-barber-jimbaran', 'best_for', (select count(*)::int from venues where slug = 'bali-barber-jimbaran' and status = 'active' and publication_status = 'published' and md5(best_for) = '70632320a8cd02e588416d6de843ba96'), md5('Men after a walk-in cut or shave near Jimbaran Bay') = 'd96201b34c220b8bc0829b0653679489'),
  (12, 'bali-beauty-salon-nusa-dua', 'best_for', (select count(*)::int from venues where slug = 'bali-beauty-salon-nusa-dua' and status = 'active' and publication_status = 'published' and md5(best_for) = 'bd4559f109d4ac64c4e5a66e4e5cf963'), md5('Salon basics off-property while you''re in the resort area') = '517e862c8c48009d5c019e1743ce034a'),
  (13, 'balquisse-heritage-hotel-yoga-jimbaran', 'why_its_here', (select count(*)::int from venues where slug = 'balquisse-heritage-hotel-yoga-jimbaran' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '0dc6211e625b0d6e7cb4de8dfbc1f001'), md5('Yoga classes in the garden of Balquisse Heritage Hotel, a boutique hotel in inner Jimbaran.') = '795e56688a0e1de7759238ce0601a187'),
  (14, 'balquisse-heritage-hotel-yoga-jimbaran', 'best_for', (select count(*)::int from venues where slug = 'balquisse-heritage-hotel-yoga-jimbaran' and status = 'active' and publication_status = 'published' and md5(best_for) = '71ceac3ab1f8b53969d230c44eb8e9dd'), md5('Guests and neighbours after a quiet, small-group class off the tourist track') = 'a97b47ce2c25df8bb134e98a847e4704'),
  (15, 'balquisse-spa-jimbaran', 'why_its_here', (select count(*)::int from venues where slug = 'balquisse-spa-jimbaran' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '6c0b31d870c22c1437075165f07c9b81'), md5('The spa at Balquisse, a Moroccan-Balinese boutique heritage hotel in inner Jimbaran, where treatments take place in an intimate setting.') = '887c824acd50239d409a5e89f4d84e77'),
  (16, 'balquisse-spa-jimbaran', 'best_for', (select count(*)::int from venues where slug = 'balquisse-spa-jimbaran' and status = 'active' and publication_status = 'published' and md5(best_for) = '05c0dc53fecf3c8543489cd56f100ecd'), md5('A characterful, non-chain spa treatment away from the beach strip') = '92a89c98434d23f1450fe70dd0e2d909'),
  (17, 'bawang-merah-beachfront', 'why_its_here', (select count(*)::int from venues where slug = 'bawang-merah-beachfront' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '326990aebdac2ee7c79c8b84df979f91'), md5(U&'A beachfront seafood restaurant with tables on the sand at Kelan Beach, the quiet northern end of Jimbaran Bay. Whole fish, prawns, squid and lobster are charcoal-grilled and sold by weight. Balinese dancers perform nightly, around 7\20139pm, as the sun sets over the Indian Ocean.') = '94627d22e5f0c35d74c038df150ce57c'),
  (18, 'bawang-merah-beachfront', 'best_for', (select count(*)::int from venues where slug = 'bawang-merah-beachfront' and status = 'active' and publication_status = 'published' and md5(best_for) = '3ed6ac644fa30742814cd5c10b5729c9'), md5('A sunset seafood dinner with your toes in the sand, for couples or groups staying clear of Jimbaran''s busier main strip') = '657f91f8546c0d9b5b5474a03a32d32f'),
  (19, 'bejana-ritz-carlton', 'why_its_here', (select count(*)::int from venues where slug = 'bejana-ritz-carlton' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '4cec3f9c57f8c5df42cd7cf971f165f3'), md5('The Indonesian restaurant at The Ritz-Carlton, Bali, on the cliffs above the Indian Ocean at Sawangan, Nusa Dua. Regional Balinese and archipelago dishes are served across three levels, including the Culinary Cave open kitchen. The centrepiece is the Archipelago Rijsttafel, a shared multi-dish rice-table feast.') = '8bbb4ae4def03fe4785a2605e2502d05'),
  (20, 'bejana-ritz-carlton', 'best_for', (select count(*)::int from venues where slug = 'bejana-ritz-carlton' and status = 'active' and publication_status = 'published' and md5(best_for) = '15bc8ada4072d5205c3edaca16b95d4a'), md5('An unhurried Indonesian dinner on a special evening, with cliff-top ocean views') = '1c76481ec6206b8bedbeb24fc432641c'),
  (21, 'brook-nusa-dua', 'why_its_here', (select count(*)::int from venues where slug = 'brook-nusa-dua' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '3ab1b3d8c0b4614c3093196841b1bc2c'), md5('A Benoa restaurant whose panoramic view takes in the airport runway as well as the Garuda statue and the ocean. The menu runs from American and European to Russian, Ukrainian and Asian dishes. It is styled like vintage Brooklyn and serves cocktails.') = '084cff2130bd271b229123a4a098f4dd'),
  (22, 'bumbu-bali', 'why_its_here', (select count(*)::int from venues where slug = 'bumbu-bali' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'caf9a0188a3f1578ead1f1c58b3ddd7b'), md5('A Balinese restaurant and cooking school on Nusa Dua''s northern edge, founded in 1996 by Swiss chef and cookbook author Heinz von Holzen. Home- and ceremony-style dishes such as babi guling and a multi-course rijsttafel are served in a traditional courtyard compound.') = 'd80d45d0502705a3fbd954d57e78e146'),
  (23, 'bumbu-bali', 'best_for', (select count(*)::int from venues where slug = 'bumbu-bali' and status = 'active' and publication_status = 'published' and md5(best_for) = '08a2882dc07a360dee840e5f9cce1bfa'), md5('Trying a wide spread of traditional Balinese cooking over dinner, or taking a market-and-cooking class') = 'c95a4641c24cbd75ea900ea03c80649b'),
  (24, 'camino-resto-and-bar', 'why_its_here', (select count(*)::int from venues where slug = 'camino-resto-and-bar' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '643682cdd1be6529b0b8a7312745da95'), md5('A Mediterranean kitchen in Jimbaran built around a grill and a smoker. The menu has frutti di mare pasta, grilled fish and salmon, and there''s molten lava cake for dessert.') = 'ac9e9b5dad1d6cb63f52cd93368115fb'),
  (25, 'canna-beach-club', 'why_its_here', (select count(*)::int from venues where slug = 'canna-beach-club' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '75ec8aa0babcd04fe051c4371be5c191'), md5('A large, multi-zone beachfront club on the southern side of Nusa Dua. It has a pool, daybeds, water sports and several dining areas, the oceanfront Cliff restaurant among them. It runs from daytime lounging into evening entertainment.') = '47cf001a739a9914287eec2d07b86c8b'),
  (26, 'canna-beach-club', 'best_for', (select count(*)::int from venues where slug = 'canna-beach-club' and status = 'active' and publication_status = 'published' and md5(best_for) = '7f3aa8137832b1d9ca7041968418913c'), md5('A full day-to-night outing for families or groups on Nusa Dua''s calm white-sand beach') = 'b3e82e7a39edcade45e625966463beb3'),
  (27, 'club-med-bali-fitness', 'why_its_here', (select count(*)::int from venues where slug = 'club-med-bali-fitness' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '68040126a38a5365c071e5c1d1400a90'), md5('The gym at the all-inclusive Club Med Bali, on the Nusa Dua ITDC estate, has a cardio room plus squash and tennis courts. Sport comes with the stay, coached by G.O. staff: padel, pickleball, archery, trapeze, plus aquafitness and water polo in the pool.') = '2078373dbb71352fddddae833a52060a'),
  (28, 'club-med-bali-fitness', 'best_for', (select count(*)::int from venues where slug = 'club-med-bali-fitness' and status = 'active' and publication_status = 'published' and md5(best_for) = '621971428adba554b7183e0466fa6656'), md5('Sport all day on one bill, from trapeze to padel, rather than a gym and nothing else') = '077b37af533c06e1549d802c5b5baa51'),
  (29, 'conrad-bali-fitness-centre', 'why_its_here', (select count(*)::int from venues where slug = 'conrad-bali-fitness-centre' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '66aed75ca33cca1399194451f9cd8a2f'), md5('Conrad Bali''s 24-hour gym in Tanjung Benoa, inside the Jiwa Spa complex. The complex also holds 17 treatment rooms, garden pavilions, a steam room, a sauna and a jacuzzi. Pilates is on the class list, and the resort has two floodlit tennis courts.') = '42f69e9b2f365302d6c43d2defea70a2'),
  (30, 'conrad-bali-fitness-centre', 'best_for', (select count(*)::int from venues where slug = 'conrad-bali-fitness-centre' and status = 'active' and publication_status = 'published' and md5(best_for) = '94431bccb72a5c3068b17bcc9da53ace'), md5('Nusa Dua and Tanjung Benoa guests who want a round-the-clock gym with spa, sauna and floodlit tennis on the same site') = '57583f0bdb652d1b60dc0535ba9fcb55'),
  (31, 'courtyard-by-marriott-nusa-dua-gym', 'why_its_here', (select count(*)::int from venues where slug = 'courtyard-by-marriott-nusa-dua-gym' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '4f6f68a05893d412f6110edcbdd8daa2'), md5(U&'Courtyard by Marriott Bali Nusa Dua''s gym, with cardio and strength equipment, open to hotel guests 24 hours. Staff are on the floor 06:00\201323:00, with key access outside those hours. Instructor-led classes are free, and the resort also has a yoga pavilion and a spa.') = '4696d2c2881197c716776c349d1142d5'),
  (32, 'courtyard-by-marriott-nusa-dua-gym', 'best_for', (select count(*)::int from venues where slug = 'courtyard-by-marriott-nusa-dua-gym' and status = 'active' and publication_status = 'published' and md5(best_for) = 'cf18eada8e08b975a5b181b361ad0e21'), md5('Free instructor-led classes on top of a 24-hour gym during a Nusa Dua stay') = '5d3bdf7cd2aeaa737506fd6d3210da5c'),
  (33, 'cuca-restaurant', 'why_its_here', (select count(*)::int from venues where slug = 'cuca-restaurant' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'a58d54f3ae784020b4f17b647502c663'), md5('A standalone Jimbaran restaurant opened in 2013 by chef Kevin Cherkas, formerly of elBulli, Arzak and Daniel. Its tapas are globally inspired and built on Indonesian ingredients; so are its cocktails and desserts.') = '36b0b1aec21c6d9ca64f2639243ac62e'),
  (34, 'cuca-restaurant', 'best_for', (select count(*)::int from venues where slug = 'cuca-restaurant' and status = 'active' and publication_status = 'published' and md5(best_for) = 'a47669633975579ac39547a878e7342b'), md5('Couples and groups after a tasting-style dinner of sharing plates, from BBQ octopus with Asian gazpacho to the Bali Breakfast dessert') = '80979401d1a8d5d1eb2ba36fd40052f3'),
  (35, 'dava-steak-and-seafood', 'why_its_here', (select count(*)::int from venues where slug = 'dava-steak-and-seafood' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '279da032aff4fca8c77dbb5b00e4bf81'), md5('The AYANA Resort''s steakhouse and seafood grill, up on Jimbaran''s clifftop with ocean and sunset views. Dry-aged and wagyu beef and Canadian lobster go over a wood-fired grill. A beef sommelier and a salt-cart sommelier are on hand, and dinner starts in the Martini Bar.') = '027f12d7846c6b2358466caedc38ba86'),
  (36, 'dava-steak-and-seafood', 'best_for', (select count(*)::int from venues where slug = 'dava-steak-and-seafood' and status = 'active' and publication_status = 'published' and md5(best_for) = '4d7099e8755a4e1d23b5f7041e175b39'), md5('A special-occasion dinner for couples or steak-and-wine lovers who want an upscale grill with a sunset ocean backdrop') = '84a3c5f4248ca0c8a7f82631b2f74205'),
  (37, 'dua-kafe-nusa-dua', 'why_its_here', (select count(*)::int from venues where slug = 'dua-kafe-nusa-dua' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '6a1de1cc6aab292ab143851f8b2b2913'), md5(U&'An all-day caf\00E9 in Nusa Dua, a short walk from the beach. Drinks include a macadamia flat white and a matcha latte.') = 'cf71717caf87786bc8cf85ec098a527b'),
  (38, 'dua-kafe-nusa-dua', 'best_for', (select count(*)::int from venues where slug = 'dua-kafe-nusa-dua' and status = 'active' and publication_status = 'published' and md5(best_for) = 'c54088168ce858d7932d262fcfb0792a'), md5('A flat white or a matcha latte in Nusa Dua') = '19296f2e097aa461933a6658db61c7bb'),
  (39, 'fore-coffee-jimbaran', 'why_its_here', (select count(*)::int from venues where slug = 'fore-coffee-jimbaran' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'c1717b46e6703f9f6096e5368aac2af1'), md5('The Jimbaran branch of Fore, a specialty-coffee chain from Indonesia with several outlets in Bali. It pulls everyday espresso and palm-sugar (aren) lattes in a modern grab-and-go format.') = '6bc3fa17752063d7f7945b8098e16da9'),
  (40, 'fore-coffee-jimbaran', 'best_for', (select count(*)::int from venues where slug = 'fore-coffee-jimbaran' and status = 'active' and publication_status = 'published' and md5(best_for) = '7f8181c4edb8e588e4ee9fe7929532e9'), md5('An affordable everyday coffee, or a quick aren latte on the go') = '11a7855c56c0dbc34045f28c9b7096a8'),
  (41, 'fore-coffee-jimbaran', 'not_for', (select count(*)::int from venues where slug = 'fore-coffee-jimbaran' and status = 'active' and publication_status = 'published' and md5(not_for) = '20f4f6852370092b14bd6b36e823ba24'), md5('A food-forward brunch or a long laptop session in a quiet, design-led room: the format is grab-and-go') = '4cf338c7d0070268b26b512d8006e51f'),
  (42, 'four-seasons-jimbaran-fitness-centre', 'why_its_here', (select count(*)::int from venues where slug = 'four-seasons-jimbaran-fitness-centre' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '038f94596911899c89d9db2f62540c00'), md5('The gym at Four Seasons Resort Bali at Jimbaran Bay is fully equipped, and the aerobics studio has a sprung floor. Personal trainers give one-off advice or build a programme for a longer stay. There is also an oceanfront bale for training and practice.') = '6170d0fa782683d575b10f73439dc79b'),
  (43, 'four-seasons-jimbaran-fitness-centre', 'best_for', (select count(*)::int from venues where slug = 'four-seasons-jimbaran-fitness-centre' and status = 'active' and publication_status = 'published' and md5(best_for) = '9720feedff5ff86e52fc6725dfdcb3c2'), md5('Resort guests who want a sprung aerobics floor and personal training rather than a room of machines') = '738cd5778bad06968788b7a363e8dbf8'),
  (44, 'four-seasons-jimbaran-yoga', 'why_its_here', (select count(*)::int from venues where slug = 'four-seasons-jimbaran-yoga' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '4508e416130173437ac01117cba476bd'), md5('The yoga and meditation programme at Four Seasons Resort Bali at Jimbaran Bay, with daily classes in Yin, Kundalini and hot stone yoga. A local teacher runs Balinese sessions on Sekala and Niskala (the seen and unseen worlds). Classes also run on the beachfront.') = '3808b8b016746b79a4d785bcb03655d2'),
  (45, 'four-seasons-jimbaran-yoga', 'best_for', (select count(*)::int from venues where slug = 'four-seasons-jimbaran-yoga' and status = 'active' and publication_status = 'published' and md5(best_for) = '798dd7a8b338232f2f4ff0ef8428bf00'), md5('Variety and depth in a yoga practice, with Balinese sessions and a visiting master in residence two weeks a month') = 'e62865cd16daaadf19031b2782fae87b'),
  (46, 'gourmet-and-cafe-nusa-dua', 'why_its_here', (select count(*)::int from venues where slug = 'gourmet-and-cafe-nusa-dua' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'b8caa5c99e3c00b31866cad1d52a36dc'), md5(U&'A caf\00E9 in Nusa Dua serving food and health-forward drinks in a cosy, considered space.') = '49771d5a2aa99b8d66dc8dbf490b7eb5'),
  (47, 'gourmet-and-cafe-nusa-dua', 'best_for', (select count(*)::int from venues where slug = 'gourmet-and-cafe-nusa-dua' and status = 'active' and publication_status = 'published' and md5(best_for) = '2129846793c5e22c0f5cb9826809ad1e'), md5('A daytime stop for food and a health-forward drink in Nusa Dua') = '28f81270f068e04e4b8d0eadf1d9bb53'),
  (48, 'grand-hyatt-bali-yoga', 'why_its_here', (select count(*)::int from venues where slug = 'grand-hyatt-bali-yoga' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '7c8bd3a18bde7116878169674c85b326'), md5('Grand Hyatt Bali runs daily yoga sessions from a dedicated studio in the Bay Club, and outdoors on the resort lawns. The lawns overlook the water lily pond, with the beach beyond.') = '480d472a37509ef59bf3a5290f1476f1'),
  (49, 'grand-hyatt-bali-yoga', 'best_for', (select count(*)::int from venues where slug = 'grand-hyatt-bali-yoga' and status = 'active' and publication_status = 'published' and md5(best_for) = '9aad3f61cd19b1abd1382a4f05ba1b2e'), md5('Guests who would rather practise outdoors on the lawns than in a studio, with an indoor room as the fallback') = '428bc762027522e101fcbbfd8d63ccfa'),
  (50, 'healing-village-spa-at-four-seasons-jimbaran-jimbaran', 'why_its_here', (select count(*)::int from venues where slug = 'healing-village-spa-at-four-seasons-jimbaran-jimbaran' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '3331e960a310c80ee0a684f76da41bab'), md5('The Healing Village Spa is on the hillside of Four Seasons Resort Bali at Jimbaran Bay, and its treatments are holistic and wellness-led.') = '636113b8c231e9b0b76dc6a180917f89'),
  (51, 'healing-village-spa-at-four-seasons-jimbaran-jimbaran', 'best_for', (select count(*)::int from venues where slug = 'healing-village-spa-at-four-seasons-jimbaran-jimbaran' and status = 'active' and publication_status = 'published' and md5(best_for) = '80e2861d16cbc3573c80a93bb3fdaeaa'), md5('A destination-spa visit for anyone prepared to pay a five-star price') = 'f60cd7606f910e7dc2b9d93163fef068'),
  (52, 'intercontinental-bali-resort-beauty-services-jimbaran', 'why_its_here', (select count(*)::int from venues where slug = 'intercontinental-bali-resort-beauty-services-jimbaran' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '3b75103acf3d3f68269b121da63ac5a9'), md5('The salon and beauty services at the InterContinental Bali Resort on Jimbaran Bay cover hair, nails and grooming, alongside the resort''s Spa Uluwatu.') = 'ce1e73b3a0f10fabb2c0031c20d3d169'),
  (53, 'intercontinental-bali-resort-beauty-services-jimbaran', 'best_for', (select count(*)::int from venues where slug = 'intercontinental-bali-resort-beauty-services-jimbaran' and status = 'active' and publication_status = 'published' and md5(best_for) = '7673f6a36a126fcacf7d2288d406da80'), md5('Salon treatments in a beachfront five-star setting, for resort guests or visitors') = 'fa49e622a2595ef899e79fcb7ff14b8c'),
  (54, 'izakaya-by-oku', 'why_its_here', (select count(*)::int from venues where slug = 'izakaya-by-oku' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'cd4a313ebd3b3b6431732c696cf1b2aa'), md5('The Apurva Kempinski Bali''s Japanese restaurant in Nusa Dua, an offshoot of OKU in Jakarta. Contemporary izakaya-style dishes come out of an open kitchen at the centre of a bistro room, so you can watch the chefs work.') = '46574a6f58852d14defd0ddb7c7383fb'),
  (55, 'izakaya-by-oku', 'best_for', (select count(*)::int from venues where slug = 'izakaya-by-oku' and status = 'active' and publication_status = 'published' and md5(best_for) = '242f4ee4a9e635bd465dcc1717e0ceaa'), md5('Apurva Kempinski guests or visitors after a polished Japanese dinner in Nusa Dua') = 'f2c216db6f94c3c787a21daebd6317cd'),
  (56, 'izakaya-by-oku', 'not_for', (select count(*)::int from venues where slug = 'izakaya-by-oku' and status = 'active' and publication_status = 'published' and (not_for is null or length(trim(not_for)) = 0)), md5('A walk-in dinner, because it is reservation-only') = 'e2e1250f9fd791a440d18dd312ba3a57'),
  (57, 'jimbaran-bay-beach-resort-spa-jimbaran', 'why_its_here', (select count(*)::int from venues where slug = 'jimbaran-bay-beach-resort-spa-jimbaran' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'd26583a21538d4ec43fc50b528c00f1a'), md5('The spa at Jimbaran Bay Beach Resort near Kedonganan does Balinese massage and other treatments, steps from the sand.') = '61508fc9afa0e3b9bf2b5532440ce158'),
  (58, 'jimbaran-bay-beach-resort-spa-jimbaran', 'best_for', (select count(*)::int from venues where slug = 'jimbaran-bay-beach-resort-spa-jimbaran' and status = 'active' and publication_status = 'published' and md5(best_for) = '24ffe23de6554779929c43b3132c3721'), md5('An easy beachfront massage on a beach day') = '3b5f9b9c463102630ef9bf88746d5faf'),
  (59, 'jimbaran-hair-beauty-studio', 'why_its_here', (select count(*)::int from venues where slug = 'jimbaran-hair-beauty-studio' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'decbcc3ffe7221de66c6048f9cf53d49'), md5('A local hair-and-beauty studio in Jimbaran for cuts, colour, nails and waxing.') = 'e0a6d51b2050fcd01961d3b70b7f9e58'),
  (60, 'jimbaran-hair-beauty-studio', 'best_for', (select count(*)::int from venues where slug = 'jimbaran-hair-beauty-studio' and status = 'active' and publication_status = 'published' and md5(best_for) = '1827007b15476910ae6216648951a17d'), md5('Salon basics while you''re staying in Jimbaran, without heading to Kuta') = '63de77edacd26dbe294ed4376cf010bc'),
  (61, 'karma-spa-at-karma-jimbaran-jimbaran', 'why_its_here', (select count(*)::int from venues where slug = 'karma-spa-at-karma-jimbaran-jimbaran' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'c50a4e2786af4f672f38a344c61e8729'), md5('Karma Spa at Karma Jimbaran, a beachside villa resort near Jimbaran Bay, runs treatments from 09:00 to 19:00.') = 'd68f0145bd292f9e041595faf89ffa97'),
  (62, 'karma-spa-at-karma-jimbaran-jimbaran', 'best_for', (select count(*)::int from venues where slug = 'karma-spa-at-karma-jimbaran-jimbaran' and status = 'active' and publication_status = 'published' and md5(best_for) = '3590f25a098e8120a6f1d4b7726a3f46'), md5('A beachside spa session while staying at the Karma resort') = 'd2ac21872dce6b9a5ef30d85c922f3ce'),
  (63, 'kayumanis-resto-jimbaran', 'why_its_here', (select count(*)::int from venues where slug = 'kayumanis-resto-jimbaran' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '4ca3dcd570e52bdb1885ade3b19f4a35'), md5('The Indonesian restaurant of the Kayumanis Jimbaran Private Estate & Spa: a replica Javanese joglo, almost entirely hardwood, in a garden of coconut palms. Archipelago classics are built on market-fresh produce and catch-of-the-day seafood; betutu duck, beef ribs and charcoal-grilled prawns are among them.') = 'd39416e1a52d91ac9e65a7c41de5c642'),
  (64, 'kayumanis-resto-jimbaran', 'best_for', (select count(*)::int from venues where slug = 'kayumanis-resto-jimbaran' and status = 'active' and publication_status = 'published' and md5(best_for) = 'dc96c2b97d4e8920a6dde8e1899bb7fb'), md5('A sit-down dinner of regional Indonesian cooking in a resort garden, as a change from Jimbaran Bay''s beachfront seafood grills') = '025b62237437270ab44bf513bc21ffb0'),
  (65, 'kayuputi', 'why_its_here', (select count(*)::int from venues where slug = 'kayuputi' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'af734f7ac1eb55dcfc864c95c46209cb'), md5('The fine-dining restaurant at The St. Regis Bali Resort in Nusa Dua, in a white, open-kitchen room facing the Indian Ocean. Pan-Asian haute cuisine comes as multi-course degustation menus, backed by an extensive wine list, and there is a champagne brunch.') = '3fa2a728fa31d0f759c3752fb13a8c87'),
  (66, 'kayuputi', 'best_for', (select count(*)::int from venues where slug = 'kayuputi' and status = 'active' and publication_status = 'published' and md5(best_for) = 'ba8173dcfab0937f96871caf11dcebbc'), md5('A special-occasion tasting-menu dinner by the ocean, or the weekend champagne brunch') = 'ae5ed8ed8bbf0395364b0512b7b69266'),
  (67, 'kenja-ikan-bakar-nusa-dua', 'why_its_here', (select count(*)::int from venues where slug = 'kenja-ikan-bakar-nusa-dua' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '2833208c3c51ae91ca0779b181b0e895'), md5('Ikan bakar and other grilled fish and shellfish are the speciality of this sit-down Indonesian restaurant on Jl. Pantai Mengiat. It is walkable from the Nusa Dua beach and ITDC area, with live music in the evening.') = 'b48d0ea8f023cc303e0e76f262df3714'),
  (68, 'kenja-ikan-bakar-nusa-dua', 'best_for', (select count(*)::int from venues where slug = 'kenja-ikan-bakar-nusa-dua' and status = 'active' and publication_status = 'published' and md5(best_for) = 'c2703f0e8bd3aab067a743cb3de69095'), md5('A comfortable, seated seafood dinner near Nusa Dua beach without the trip to Jimbaran') = '3929c274149bd42d5b9700bcfb781b02'),
  (69, 'kenja-ikan-bakar-nusa-dua', 'not_for', (select count(*)::int from venues where slug = 'kenja-ikan-bakar-nusa-dua' and status = 'active' and publication_status = 'published' and md5(not_for) = 'fec24e3be7099294bc0868572c73f671'), md5('A budget meal at warung prices. This is a sit-down restaurant') = '02aaeac03bcbf7e3094b95f1f3bd7223'),
  (70, 'koral', 'why_its_here', (select count(*)::int from venues where slug = 'koral' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'a9f58310d96b52888f306277913a7a2a'), md5('An aquarium restaurant inside The Apurva Kempinski Bali on Nusa Dua, where tables sit against large tanks holding 80-plus marine species. Degustation menus focus on seafood, drawing on Indonesian coastal flavours and local ingredients, with wine pairings and a cocktail station.') = '9b6384c31e434b16bef0e5a2abfacd08'),
  (71, 'koral', 'best_for', (select count(*)::int from venues where slug = 'koral' and status = 'active' and publication_status = 'published' and md5(best_for) = '6e768cb1a0c88f96b0f9fd4d0993d64a'), md5('A multi-course seafood tasting menu in an unusual aquarium setting, on a special occasion for couples or design-minded diners') = '8865005794683126092143b81ed1a3da'),
  (72, 'kriya-spa-at-grand-hyatt-bali-nusa-dua', 'why_its_here', (select count(*)::int from venues where slug = 'kriya-spa-at-grand-hyatt-bali-nusa-dua' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '20f193ae0b791179a05990b02a924240'), md5('Kriya Spa sits in the Grand Hyatt Bali''s water-palace-inspired grounds, with garden gazebos beside tropical pools. Its menu is organised around themed rituals (Bliss, Harmony, Purity, Energy) rooted in traditional Balinese and Javanese wellness.') = 'fd2f220098935d8ac86ad1e5f7fdc77f'),
  (73, 'kriya-spa-at-grand-hyatt-bali-nusa-dua', 'best_for', (select count(*)::int from venues where slug = 'kriya-spa-at-grand-hyatt-bali-nusa-dua' and status = 'active' and publication_status = 'published' and md5(best_for) = '201afd8dde965f6d3456c5fe01d828f3'), md5('A traditional Balinese massage or a heritage-style Lulur ritual in an open garden pavilion, for resort guests and couples') = 'ab31f80dc1d416c56f284b6bafcf2c5f'),
  (74, 'kriya-spa-at-grand-hyatt-bali-nusa-dua', 'not_for', (select count(*)::int from venues where slug = 'kriya-spa-at-grand-hyatt-bali-nusa-dua' and status = 'active' and publication_status = 'published' and md5(not_for) = '114fae73815109344509759bfc251169'), md5('A clinical urban day spa or the cheapest option in the area: Kriya''s treatments are themed rituals in garden gazebos') = '73e8cb93fdd797daecb215ccffb8ef9b'),
  (75, 'kubu-garden-restaurant', 'why_its_here', (select count(*)::int from venues where slug = 'kubu-garden-restaurant' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '1e9d87a582b3567fe85ec4778907a233'), md5('The all-day restaurant and coffee spot of Kubu Garden Suites, on Jl. Pratama in Tanjung Benoa. The kitchen cooks Indonesian, Western and Italian dishes, and the bread is baked in-house.') = 'ce340f7a8458beb2b877e8f4d131844d'),
  (76, 'kubu-garden-restaurant', 'best_for', (select count(*)::int from venues where slug = 'kubu-garden-restaurant' and status = 'active' and publication_status = 'published' and md5(best_for) = '8cf76890428d4a2684255f8f558a24b1'), md5('A calm sit-down meal or an all-day breakfast near Nusa Dua') = 'fbc223c28c5730b4e463a1931ad218fd'),
  (77, 'kubu-garden-restaurant', 'not_for', (select count(*)::int from venues where slug = 'kubu-garden-restaurant' and status = 'active' and publication_status = 'published' and (not_for is null or length(trim(not_for)) = 0)), md5('A view or a scene, because it has neither') = '9efaf8ceeb63f63fd7d65d1093ff751f'),
  (78, 'manarai-beach-house', 'why_its_here', (select count(*)::int from venues where slug = 'manarai-beach-house' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '1c266bca0d06d87239f93b3cad510daf'), md5('An ISMAYA beach club on the white-sand beachfront of the Sofitel Bali Nusa Dua Beach Resort. A restaurant leads through an outdoor lounge to two infinity pools and daybeds on the sand. Three bars, an all-day international and Balinese menu, and DJ sets at sunset.') = 'cc655aca2f6320b93cbafc6a3fa43e43'),
  (79, 'manarai-beach-house', 'best_for', (select count(*)::int from venues where slug = 'manarai-beach-house' and status = 'active' and publication_status = 'published' and md5(best_for) = 'dc11d7231a5abfb09527f0a29d61a215'), md5('Resort-goers and couples after a full pool-and-beach day with no entrance fee or minimum spend, from midday into the golden-hour DJ hours') = '15771e58c2979b630a0e49391ad44081'),
  (80, 'martha-tilaar-salon-day-spa-jimbaran', 'why_its_here', (select count(*)::int from venues where slug = 'martha-tilaar-salon-day-spa-jimbaran' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '0a3cef4bcfe28d167fda64a4fd489d21'), md5('A Jimbaran salon and day spa from Martha Tilaar, Indonesia''s homegrown beauty house. Traditional Javanese-Balinese rituals sit alongside everyday hair and nail services.') = 'e4caab48c85320e915d4b40a2b71eadb'),
  (81, 'martha-tilaar-salon-day-spa-jimbaran', 'best_for', (select count(*)::int from venues where slug = 'martha-tilaar-salon-day-spa-jimbaran' and status = 'active' and publication_status = 'published' and md5(best_for) = '32a5b547ad3cfbc5e3809ce1be613e37'), md5('Traditional Indonesian spa rituals from a local brand') = '2ceee7366fff6079e29d1c46324ec787'),
  (82, 'mulia-fitness-centre-nusa-dua', 'why_its_here', (select count(*)::int from venues where slug = 'mulia-fitness-centre-nusa-dua' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '057a580945d30ff17266ddecb587a9f4'), md5('The Mulia''s resort gym on Geger beach is large and fully equipped, with cardio and weights. A movement studio runs group classes, and the racquet facilities include tennis and pickleball.') = '7cad28fa463a5b23d2519103a90b245c'),
  (83, 'mulia-fitness-centre-nusa-dua', 'best_for', (select count(*)::int from venues where slug = 'mulia-fitness-centre-nusa-dua' and status = 'active' and publication_status = 'published' and md5(best_for) = '01c7b84cfff0e361a6317b376bab262c'), md5('Resort guests who want a well-equipped gym and group classes without leaving the Nusa Dua strip') = 'ed957538a5a75beed34ada41392f7bb6'),
  (84, 'mulia-spa-nusa-dua', 'why_its_here', (select count(*)::int from venues where slug = 'mulia-spa-nusa-dua' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'ae46d88d374c46098a698ce2abb1b781'), md5('The Mulia''s 20-room spa, built around a hydrotherapy circuit that guests move through before a tailored, Ayurvedic-inspired treatment. The circuit takes in hot and cold plunge pools, Finnish saunas, steam and ice rooms, and Cleopatra-style hydrotonic pools with underwater jets.') = 'a0717430efdfb00d2550fa56d873659f'),
  (85, 'mulia-spa-nusa-dua', 'best_for', (select count(*)::int from venues where slug = 'mulia-spa-nusa-dua' and status = 'active' and publication_status = 'published' and md5(best_for) = 'ca03b4ea0f1beefdeba6bf2d872660f7'), md5('A full half-day wellness ritual with pools, saunas and a long massage, for couples staying on the Nusa Dua/Sawangan strip') = '666780bdec1175728912a69e1f118191'),
  (86, 'mulia-spa-nusa-dua', 'not_for', (select count(*)::int from venues where slug = 'mulia-spa-nusa-dua' and status = 'active' and publication_status = 'published' and md5(not_for) = '446a1f7d9f44c69cadcd28c15c7f091f'), md5('A fast, low-key neighbourhood massage or a budget price point. The ritual here takes half a day') = '2f45de6b667adea082a46476ba3385cd'),
  (87, 'nasi-banjar-mbok-mang', 'best_for', (select count(*)::int from venues where slug = 'nasi-banjar-mbok-mang' and status = 'active' and publication_status = 'published' and md5(best_for) = 'fded3856ac9c035668f3a2ba26ce8f36'), md5('An early pork-based Balinese breakfast or lunch at a local, non-touristy warung near Nusa Dua') = '25ace7810c425caefbde87a2b0f59475'),
  (88, 'nasi-banjar-mbok-mang', 'not_for', (select count(*)::int from venues where slug = 'nasi-banjar-mbok-mang' and status = 'active' and publication_status = 'published' and md5(not_for) = '0988f5deb68a71f972f54135ee1ce4db'), md5('Halal diners, non-pork eaters and late risers: the plate is pork-forward, and the warung opens mornings only') = '916bead25e52eef446c0b8b0b0234c78'),
  (89, 'nusa-dua-beach-grill', 'why_its_here', (select count(*)::int from venues where slug = 'nusa-dua-beach-grill' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'e593ba2e28cc6ded52923b4d1572d836'), md5('An independent, family-run beachfront restaurant on the sand at Geger Beach, Nusa Dua, running since 1995. Grilled seafood (prawns, fish, lobster) shares the menu with Indonesian and Western dishes and pastas. Tables look over the calm turquoise Geger Lagoon, a short walk from The Mulia.') = '155a9c240544537dc25ac33ea3859871'),
  (90, 'nusa-dua-beach-grill', 'best_for', (select count(*)::int from venues where slug = 'nusa-dua-beach-grill' and status = 'active' and publication_status = 'published' and md5(best_for) = '613a32bd2e22da35d50035feeeaa89d6'), md5('Families after fresh seafood on the sand without resort prices, from breakfast to sunset dinner, with a swim or snorkel in the lagoon') = 'd2fdecd969b0fd2965351caaf6284724'),
  (91, 'nyoman-cafe', 'why_its_here', (select count(*)::int from venues where slug = 'nyoman-cafe' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '14ee7bb124c91cae0af968ca519c5b3d'), md5(U&'Nyoman Caf\00E9 has been grilling seafood on the Jimbaran Bay sands, along the Muaya Beach strip, since 1994. You pick lobster, prawns, crab, snapper or squid from the tanks to be barbecued and served at candlelit tables on the beach.') = 'ce3d1297d6a7240e331b3c46536a34ea'),
  (92, 'nyoman-cafe', 'best_for', (select count(*)::int from venues where slug = 'nyoman-cafe' and status = 'active' and publication_status = 'published' and md5(best_for) = '57ceedab7ba4366e41cd0294a3ceef43'), md5('A candlelit seafood dinner at sunset, feet near the sand, for couples and groups') = 'd25642dc2c453c334a967b1b0a932f15'),
  (93, 'pantai-jimbaran', 'why_its_here', (select count(*)::int from venues where slug = 'pantai-jimbaran' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'a4b97741bb4565487038485e7c45e22f'), md5('A curving bay south of the airport in Badung, with calm water, sunset views and beachfront seafood grills.') = '964f757981444d6fbc7516a86586edc6'),
  (94, 'pantai-jimbaran', 'best_for', (select count(*)::int from venues where slug = 'pantai-jimbaran' and status = 'active' and publication_status = 'published' and md5(best_for) = 'f7d53c9ea2c48478c08d96cdbad150c2'), md5('A sunset seafood dinner on the sand, or a swim in calmer water than Kuta''s') = '9020154fd66a0317c13d484fd9e0253c'),
  (95, 'piasan', 'why_its_here', (select count(*)::int from venues where slug = 'piasan' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '58f1e1fde30d4a7e3194071a0a0e4688'), md5('An Italian restaurant at Kayumanis Nusa Dua Private Villa & Spa, in a glass-and-bamboo room over manicured gardens. Homemade pasta and wood-fired pizza sit beside prime cuts. The Bistecca di Angus Nero alla Griglia is chargrilled Black Angus steak with risotto, portobello and red-wine sauce.') = 'ae211b95309a33a575cc412188f5ad25'),
  (96, 'piasan', 'best_for', (select count(*)::int from venues where slug = 'piasan' and status = 'active' and publication_status = 'published' and md5(best_for) = 'e3fe9fa458856f263eb2d5efb4751fa0'), md5('Couples or small groups after an unhurried Italian dinner in a quiet garden, away from the beach crowds') = 'bea46932137ffe4f3868adc3dee91ea2'),
  (97, 'piramid-spa', 'why_its_here', (select count(*)::int from venues where slug = 'piramid-spa' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'b08eda9bedcfec4581ca6369e3eaaf9e'), md5('A large Jimbaran day spa whose treatment huts are pyramid-shaped and stand over a koi pond. You can book Balinese massage, body scrubs or specialty treatments, and there is a cafe on site.') = '9535ca9dbd841b8e23b3c430d7dcda44'),
  (98, 'piramid-spa', 'best_for', (select count(*)::int from venues where slug = 'piramid-spa' and status = 'active' and publication_status = 'published' and md5(best_for) = '7355d4d05e135b3510a1db70fd162385'), md5('An affordable, photogenic spa session, often a couples'' outing in the private pyramid rooms') = 'bbcbc5d327171776f6127f2e9fe47605'),
  (99, 'radja-seafood-cafe', 'why_its_here', (select count(*)::int from venues where slug = 'radja-seafood-cafe' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'f13c0ae6f13d26358abec22325678af8'), md5('Radja is a beachfront seafood grill on Muaya Beach in Jimbaran Bay, with tables set out on the sand. You choose fish, prawns, clams or lobster from an iced display, and it goes on the charcoal grill. The sun sets over the bay.') = '3fe7d05d73dfc9f1f75be50b335b1ffe'),
  (100, 'radja-seafood-cafe', 'best_for', (select count(*)::int from venues where slug = 'radja-seafood-cafe' and status = 'active' and publication_status = 'published' and md5(best_for) = '33fdf88351e559d42c780b248911a3b0'), md5('Timing a casual seafood dinner on the sand to the Jimbaran sunset, as a couple or a group') = 'c32a6e2421efe6eb3e02e9a88f2f3dc7'),
  (101, 'rev-v-wellness-resort-fitness', 'best_for', (select count(*)::int from venues where slug = 'rev-v-wellness-resort-fitness' and status = 'active' and publication_status = 'published' and md5(best_for) = '9100f4632fd0459a8204bfcffebe5303'), md5('Guests on a structured wellness or fitness programme') = '9dad01310a6df36fdc61e68e51059ccc'),
  (102, 'revi-vo-spa-wellness-nusa-dua', 'best_for', (select count(*)::int from venues where slug = 'revi-vo-spa-wellness-nusa-dua' and status = 'active' and publication_status = 'published' and md5(best_for) = 'd166dff97e4dc22a0a9d467dc146360e'), md5('A structured, results-oriented multi-day wellness programme, or a treatment beyond a standard hotel spa') = 'ff63f7326e71d07898c715003c457ec7'),
  (103, 'revi-vo-spa-wellness-nusa-dua', 'not_for', (select count(*)::int from venues where slug = 'revi-vo-spa-wellness-nusa-dua' and status = 'active' and publication_status = 'published' and md5(not_for) = 'bfa7185f79240e2b8966d709e1ff16bc'), md5('A quick, casual walk-in massage, because the spa is built around doctor-guided programmes') = '823a9f88ce31efc33a8e7902d9555f57'),
  (104, 'revi-vo-yoga-mindfulness-nusa-dua', 'why_its_here', (select count(*)::int from venues where slug = 'revi-vo-yoga-mindfulness-nusa-dua' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '967c9771301f88585d3b2683f1537c85'), md5(U&'REV\012AV\014C Wellness Resort in Sawangan, Nusa Dua, runs its yoga and mindfulness programme in a dedicated yoga space and on an aerial-yoga deck. Guided meditation is part of its wellness retreats.') = '80716f486d5051cdddb53941b93ab43b'),
  (105, 'revi-vo-yoga-mindfulness-nusa-dua', 'best_for', (select count(*)::int from venues where slug = 'revi-vo-yoga-mindfulness-nusa-dua' and status = 'active' and publication_status = 'published' and md5(best_for) = '4b0570580b63b7bda713f26961f0bbe2'), md5('Structured yoga, aerial yoga and guided mindfulness on a cliff top, for retreat guests and other travellers') = '81408c96db3e35e7b4e73de1cd423fe9'),
  (106, 'revi-vo-yoga-mindfulness-nusa-dua', 'not_for', (select count(*)::int from venues where slug = 'revi-vo-yoga-mindfulness-nusa-dua' and status = 'active' and publication_status = 'published' and md5(not_for) = '16f53210f0a1a2803d0cfbd5829d79c4'), md5(U&'A cheap drop-in neighbourhood class \2014 the yoga here comes as a retreat-style programme') = '7e24458c22a810968298e922d00991d3'),
  (107, 'signa-cafe', 'why_its_here', (select count(*)::int from venues where slug = 'signa-cafe' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '22577d725abd79fd1055ca0223663059'), md5('A family runs this Benoa cafe on Jl. Raya Kampial, and breakfast is served all day. There''s coffee, plus gourmet pizza, pasta, wraps, desserts and cocktails. It also does delivery and takeaway.') = 'c1946f62de47124d1f6e639015810d35'),
  (108, 'sofitel-bali-fitness-centre-nusa-dua', 'why_its_here', (select count(*)::int from venues where slug = 'sofitel-bali-fitness-centre-nusa-dua' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '1535916b1047e5e35312ba7093c85ea3'), md5('SoFIT is the beachfront gym at Sofitel Bali Nusa Dua Beach Resort, with cardio and strength equipment plus sauna and steam. Its class schedule runs from boxing and HIIT to aqua fitness.') = '8473686345e245d63532c465fe0193d3'),
  (109, 'sofitel-bali-fitness-centre-nusa-dua', 'best_for', (select count(*)::int from venues where slug = 'sofitel-bali-fitness-centre-nusa-dua' and status = 'active' and publication_status = 'published' and md5(best_for) = '6e96a68636eaa581c2f44618b2772211'), md5('A beachfront workout with a class timetable and recovery facilities, for Sofitel and Nusa Dua guests') = 'dd35e30447de949e972e5270d448b3cb'),
  (110, 'sofitel-bali-fitness-centre-nusa-dua', 'not_for', (select count(*)::int from venues where slug = 'sofitel-bali-fitness-centre-nusa-dua' and status = 'active' and publication_status = 'published' and md5(not_for) = 'c350c290ca30c003233302b3f108473e'), md5('A powerlifting-focused gym or a standalone budget option: SoFIT is a resort gym with a class timetable') = '90b3ba16b9ab298ff6fce121a165fcc1'),
  (111, 'sofitel-bali-yoga', 'why_its_here', (select count(*)::int from venues where slug = 'sofitel-bali-yoga' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '2c4c264e13160e90d8e1f51beb780c7e'), md5('Sofitel Bali Nusa Dua runs yoga on Mondays, Thursdays and Sundays, at IDR 150,000++ per person for an hour. Private yoga and meditation cost extra, and so do Qi Gong and inner-power sessions. Beach yoga is on the resort activity list too.') = 'e79ea604ae27282f51cda869f47c98b3'),
  (112, 'sofitel-bali-yoga', 'best_for', (select count(*)::int from venues where slug = 'sofitel-bali-yoga' and status = 'active' and publication_status = 'published' and md5(best_for) = '846100a96633168b95a707b8e4a6acfc'), md5('Nusa Dua guests who want a paid scheduled class a few times a week, with private sessions available on request') = '721a841e5502a961aa905e97246af4e0'),
  (113, 'soleil-at-mulia', 'why_its_here', (select count(*)::int from venues where slug = 'soleil-at-mulia' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '59a63acab18d15a6904c7b326bcfcaa2'), md5('The beachfront restaurant at The Mulia, Mulia Resort & Villas in Nusa Dua, facing the Indian Ocean from indoor and terrace tables. Mediterranean and Pan-Asian dishes run from handcrafted pastas to grilled seafood. Sunday Brunch adds a seafood bar, live grill stations and Italian antipasti.') = '86ae15e5869c72c48d70e3677bf1d384'),
  (114, 'soleil-at-mulia', 'best_for', (select count(*)::int from venues where slug = 'soleil-at-mulia' and status = 'active' and publication_status = 'published' and md5(best_for) = 'f200bbd078f2bcbfd3056937319c6ebe'), md5(U&'Couples and groups after an oceanfront occasion meal, or the Sunday Brunch (11am\20133pm)') = 'c17cf0938d08a668c6b42d0c78d9796b'),
  (115, 'st-regis-bali-athletic-club', 'why_its_here', (select count(*)::int from venues where slug = 'st-regis-bali-athletic-club' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '5c089f6f3ece505e35c7b6c4f6f38e5e'), md5('The St. Regis Bali Resort''s 24-hour gym sits inside its Iridium Spa in Nusa Dua. Life Fitness equipment is split into zones for strength, cardio and movement work, and personal trainers can be booked.') = '85c13f8c27986e2e35739441f5087652'),
  (116, 'st-regis-bali-athletic-club', 'best_for', (select count(*)::int from venues where slug = 'st-regis-bali-athletic-club' and status = 'active' and publication_status = 'published' and md5(best_for) = '1899d0faa6ba73413b8295600be56910'), md5('A full 24-hour gym with the option of a personal trainer, without leaving the resort') = '3cc8648b7e18c83125e4d168cbdf0838'),
  (117, 'sundara', 'why_its_here', (select count(*)::int from venues where slug = 'sundara' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '4bac0b711cc860ca6678cf0b1cdf6b18'), md5(U&'The beach club and beachfront restaurant at the Four Seasons Resort Bali at Jimbaran Bay. It steps down from a bar and daybeds to a 57-metre infinity pool and the sand. Seafood and charred meats are cooked over fire, and Sunday brings a ros\00E9 brunch.') = '744a5a0d07c8a7686893567c9399951e'),
  (118, 'sundara', 'best_for', (select count(*)::int from venues where slug = 'sundara' and status = 'active' and publication_status = 'published' and md5(best_for) = 'd5c6a4866663b147b24697421530680d'), md5(U&'Sunset drinks and daybeds by the pool, or a special-occasion seafood dinner and the Sunday ros\00E9 brunch') = '4a07a1656173b94009eb65ab90423ef1'),
  (119, 'sunset-beach-bar-and-grill', 'why_its_here', (select count(*)::int from venues where slug = 'sunset-beach-bar-and-grill' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'eacdc020cc8c264a48165d1b8a3675e2'), md5('The InterContinental Bali Resort''s open-air beach bar on Jimbaran Bay, with your toes in the white sand among coconut palms. The view runs 180 degrees west over the water. Grilled dishes and cocktails come with live music every day as the sun goes down.') = '594dd97fdc0adce0d85786ead64bff51'),
  (120, 'sunset-beach-bar-and-grill', 'best_for', (select count(*)::int from venues where slug = 'sunset-beach-bar-and-grill' and status = 'active' and publication_status = 'published' and md5(best_for) = '61dd3f87d4d98214ca1d19f4cc3df0c7'), md5('Couples and groups who want a beach-facing table or bean bag for late-afternoon drinks and grilled bites timed to the Jimbaran Bay sunset') = '5b597be549a6198fb4e8717c5949ec84'),
  (121, 'tetaring', 'why_its_here', (select count(*)::int from venues where slug = 'tetaring' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '6ded38afcd8002ec04feec4dcb18c3ec'), md5('A modern Indonesian restaurant at Kayumanis Nusa Dua Private Villa and Spa, named after a ceremonial roof structure of bamboo and palm fronds. Its glass-walled, bamboo-accented room serves archipelago dishes such as lemongrass Balinese chicken salad and black oxtail soup.') = 'c98de38dfd0c999bd379847ad2ca2007'),
  (122, 'tetaring', 'best_for', (select count(*)::int from venues where slug = 'tetaring' and status = 'active' and publication_status = 'published' and md5(best_for) = '4f3e03acff06f60d1f63761cd8b8ec64'), md5('A lunch or dinner of regional Indonesian cooking in a quiet resort setting') = '1404e045d702a6323b95ff547e5742b9'),
  (123, 'tetaring', 'not_for', (select count(*)::int from venues where slug = 'tetaring' and status = 'active' and publication_status = 'published' and (not_for is null or length(trim(not_for)) = 0)), md5('A beachfront scene. Meals are served in a glass-walled room at a quiet resort') = 'c9f9fbd9d2fbe5f40d52c8db957649e1'),
  (124, 'the-apurva-kempinski-fitness-centre-nusa-dua', 'why_its_here', (select count(*)::int from venues where slug = 'the-apurva-kempinski-fitness-centre-nusa-dua' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '26d0c79fe93acd5dc163407f70c13645'), md5('The Apurva Kempinski''s ocean-view resort gym, on the tiered clifftop, opens early and closes late. It has modern cardio and strength equipment, and trainers lead sessions.') = '99ac49d6e5c1607c1cc4568c42bcdcab'),
  (125, 'the-apurva-kempinski-fitness-centre-nusa-dua', 'best_for', (select count(*)::int from venues where slug = 'the-apurva-kempinski-fitness-centre-nusa-dua' and status = 'active' and publication_status = 'published' and md5(best_for) = '0452c2e778ceacb02700feb3b3a6e5ef'), md5('Apurva guests who want a well-equipped, ocean-view gym with the option of a personal trainer during a resort stay') = 'a5fa09480d6f9921abc066cd9f5d79c4'),
  (126, 'the-apurva-kempinski-fitness-centre-nusa-dua', 'not_for', (select count(*)::int from venues where slug = 'the-apurva-kempinski-fitness-centre-nusa-dua' and status = 'active' and publication_status = 'published' and md5(not_for) = '6cfdd65cf1437fc10314dff89604fbf6'), md5('Non-guests after a casual drop-in gym or a group-class community, because it is a resort gym') = 'cd01834719ccfa950f386f1c50d81910'),
  (127, 'the-apurva-kempinski-yoga-nusa-dua', 'why_its_here', (select count(*)::int from venues where slug = 'the-apurva-kempinski-yoga-nusa-dua' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '10fc9c8b0eb7cb2cb00f75050d83a576'), md5('Yoga at The Apurva Kempinski means sunrise Hatha and flow classes on the beach, plus aerial anti-gravity yoga and sound-healing sessions. The resort''s clifftop and the ocean are the backdrop.') = 'e5751358f15a279599cb52045e5c8cdb'),
  (128, 'the-apurva-kempinski-yoga-nusa-dua', 'best_for', (select count(*)::int from venues where slug = 'the-apurva-kempinski-yoga-nusa-dua' and status = 'active' and publication_status = 'published' and md5(best_for) = '32f60391ada826c70a88fec081a9b6a7'), md5('A scenic sunrise beach class, or a novelty aerial or sound-healing session during a stay') = 'eae81cd8728277146e8925bb40c7104e'),
  (129, 'the-apurva-kempinski-yoga-nusa-dua', 'not_for', (select count(*)::int from venues where slug = 'the-apurva-kempinski-yoga-nusa-dua' and status = 'active' and publication_status = 'published' and md5(not_for) = 'c251d9ffed137cbbc26386dcc3a6e515'), md5('Dedicated practitioners who want a full independent studio timetable: the classes belong to a resort programme') = 'de1081b5b0248f978209914ff602e43e'),
  (130, 'the-apurva-spa-nusa-dua', 'why_its_here', (select count(*)::int from venues where slug = 'the-apurva-spa-nusa-dua' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '1909900a48802d34b76ed6b2356ce0f7'), md5('The Apurva Spa is part of The Apurva Kempinski, on the resort''s tiered clifftop above the Indian Ocean. Its treatments draw on traditional Balinese and Javanese healing: Lulur and Jamu rituals, sound healing and chakra work.') = 'b73c305ac7991818bfac7b51c0a85ad6'),
  (131, 'the-apurva-spa-nusa-dua', 'best_for', (select count(*)::int from venues where slug = 'the-apurva-spa-nusa-dua' and status = 'active' and publication_status = 'published' and md5(best_for) = '8c9e15cfbef81e2111c877301d56f7e7'), md5('A story-led Indonesian treatment on a clifftop, or a massage paired with sound-healing or chakra sessions') = 'e50b4de650430db8d5193c3048f424f9'),
  (132, 'the-apurva-spa-nusa-dua', 'not_for', (select count(*)::int from venues where slug = 'the-apurva-spa-nusa-dua' and status = 'active' and publication_status = 'published' and md5(not_for) = '52fcf04855b0ee9ea06924c6d1c58a48'), md5('A simple, walk-in street-side massage or a quick express stop. Treatments here are story-led rituals') = '88e60cf03cae13a9a50cc6b2852e8557'),
  (133, 'the-bale-nusa-dua-yoga', 'why_its_here', (select count(*)::int from venues where slug = 'the-bale-nusa-dua-yoga' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'c57fc46d0c007b113dbb104124d27bc3'), md5(U&'Private yoga rooms at The Bal\00E9 Nusa Dua, an adults-oriented retreat of 29 pavilions in Geger, each with its own pool. Yoga and pranayama are on the wellness menu with massage, energy treatments and detox programmes. There''s also a fitness centre and a quiet library.') = '2f0bd4f5d6eb7eaf82b8ae98b3ba54b1'),
  (134, 'the-bale-nusa-dua-yoga', 'best_for', (select count(*)::int from venues where slug = 'the-bale-nusa-dua-yoga' and status = 'active' and publication_status = 'published' and md5(best_for) = '8de3c6fb0a0f01f188ea30b42ddb956e'), md5('One-to-one practice in a private room rather than a group class') = 'ab29e20ac6380609f4189dfd6a0d8999'),
  (135, 'the-beach-grill-ritz-carlton', 'why_its_here', (select count(*)::int from venues where slug = 'the-beach-grill-ritz-carlton' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'f5f77b2e099882c4fe811f393cba18bc'), md5('At The Ritz-Carlton, Bali in Nusa Dua, this beachfront grill faces the Indian Ocean from indoor and outdoor tables. Premium meats and locally sourced seafood, such as barramundi, snapper and king prawn, go into a Josper charcoal oven. The menu rotates monthly around seasonal ingredients.') = '1b529fd0eb76514a5a00d5c411540531'),
  (136, 'the-beach-grill-ritz-carlton', 'best_for', (select count(*)::int from venues where slug = 'the-beach-grill-ritz-carlton' and status = 'active' and publication_status = 'published' and md5(best_for) = '2dc12431f3b48dc5e71073c775747553'), md5('Couples and resort guests after a grilled-seafood lunch, a candlelit oceanfront dinner or a private beach dinner for two') = '44bb932e7ab182c31ade292b3ce728f7'),
  (137, 'thermes-marins-bali-spa-at-ayana-jimbaran', 'why_its_here', (select count(*)::int from venues where slug = 'thermes-marins-bali-spa-at-ayana-jimbaran' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '5abc790abb21e133ea86a180f18bb0bc'), md5('Thermes Marins Bali at AYANA Resort, a seawater-therapy destination spa on the Jimbaran clifftop with an Aquatonic pool.') = '6abd633ca532e1ed77f6fdfa89c0d864'),
  (138, 'thermes-marins-bali-spa-at-ayana-jimbaran', 'best_for', (select count(*)::int from venues where slug = 'thermes-marins-bali-spa-at-ayana-jimbaran' and status = 'active' and publication_status = 'published' and md5(best_for) = '6264fc7d7827f7fca81ca8046b850ed2'), md5('A spa day with the Aquatonic pool') = '6b758c85b650f6222d2eb2b6505ca01c'),
  (139, 'unique-rooftop-bar-and-restaurant', 'why_its_here', (select count(*)::int from venues where slug = 'unique-rooftop-bar-and-restaurant' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'b84e0a045b97661886330204d38c7194'), md5('A two-level rooftop bar and pool club on top of RIMBA by AYANA in Jimbaran. Modern Mexican plates and tequila-led cocktails are served around a 25-metre infinity pool. The view takes in the Uluwatu hills and the Indian Ocean sunset.') = '4516aad8086e8e357a11bb214bf8f7b0'),
  (140, 'unique-rooftop-bar-and-restaurant', 'best_for', (select count(*)::int from venues where slug = 'unique-rooftop-bar-and-restaurant' and status = 'active' and publication_status = 'published' and md5(best_for) = '6cbe60d5f8b9567ec4da7c21521e0442'), md5('A poolside afternoon on the roof that rolls into sunset drinks and dinner, for couples or groups') = '3b1e16cfcc832f86f2b16a2f0647039c'),
  (141, 'warung-batan-bekul', 'best_for', (select count(*)::int from venues where slug = 'warung-batan-bekul' and status = 'active' and publication_status = 'published' and md5(best_for) = '1c5c8f2019c3e80be3528de6ab20d915'), md5('Fresh, Balinese-spiced grilled fish at local prices, if you''ll reserve ahead and arrive early') = 'be3918ca37f8afa2f6272f897182dbbf'),
  (142, 'warung-batan-bekul', 'not_for', (select count(*)::int from venues where slug = 'warung-batan-bekul' and status = 'active' and publication_status = 'published' and md5(not_for) = 'af0815775d2e71157af7e7848dd29453'), md5('A spontaneous walk-in or an evening meal, because it opens at midday and sells out early') = '86a37dba96c3892bb827ea4180e92b9c'),
  (143, 'warung-dobiel-nusa-dua', 'why_its_here', (select count(*)::int from venues where slug = 'warung-dobiel-nusa-dua' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'e86e1e4fb84c8290c0c4141c97d401e3'), md5('A babi guling (Balinese suckling pork) warung in Bualu village, on Jl. Srikandi, a short trip from the Nusa Dua resort gates. It serves a pork plate and a rich pork soup, and there is often a queue before opening.') = '6b5cc7f8d8fdb3b8dd23dfb57cfe8bfc'),
  (144, 'warung-dobiel-nusa-dua', 'best_for', (select count(*)::int from venues where slug = 'warung-dobiel-nusa-dua' and status = 'active' and publication_status = 'published' and md5(best_for) = '5c562d588ce30210a7c78552aaf688af'), md5('Babi guling lovers happy to go early, or anyone in Nusa Dua after an affordable local meal as a contrast to resort dining') = 'f87900c1dea6603222fce8d3f0ad6c14'),
  (145, 'warung-halme-ikan-bakar-ala-jimbaran', 'why_its_here', (select count(*)::int from venues where slug = 'warung-halme-ikan-bakar-ala-jimbaran' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '33a3ffc536b808b6ee470506ee4f53bb'), md5('A casual warung grilling Jimbaran-style ikan bakar without the trip to Jimbaran itself. Prices are cheaper than on the Jimbaran beach seafood strip.') = 'e4b15dc8114978a4504a8b30697ef3fd'),
  (146, 'warung-halme-ikan-bakar-ala-jimbaran', 'best_for', (select count(*)::int from venues where slug = 'warung-halme-ikan-bakar-ala-jimbaran' and status = 'active' and publication_status = 'published' and md5(best_for) = 'c54faf6bb01d622596a674fe5f3c6298'), md5('Jimbaran-style grilled fish and prawns close to Nusa Dua and Benoa at lunch or dinner, including for a group sharing') = '343a085605dbfc962c4d368c85764d7f'),
  (147, 'warung-halme-ikan-bakar-ala-jimbaran', 'not_for', (select count(*)::int from venues where slug = 'warung-halme-ikan-bakar-ala-jimbaran' and status = 'active' and publication_status = 'published' and md5(not_for) = 'd57ac589ef24419b50330d09b75e0389'), md5('Non-seafood eaters, or anyone after fine dining or a beachfront setting: the menu is grilled seafood in a casual warung') = '54dacb4c84b8b0b796c7b453c0501cb3'),
  (148, 'warung-mami-ikan-bakar', 'why_its_here', (select count(*)::int from venues where slug = 'warung-mami-ikan-bakar' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'b343ff99b454ac9f8b8f1d63117d2b00'), md5('Just three things go on the grill at this no-frills, family-run roadside seafood warung on Jalan Uluwatu II, Jimbaran: fish, prawns and clams. They come with three sambals plus free plecing kangkung and raw vegetables. On any day the catch isn''t fresh, it closes entirely.') = 'd86ec04e02d4ce8b3a39f79004afc00b'),
  (149, 'warung-mami-ikan-bakar', 'best_for', (select count(*)::int from venues where slug = 'warung-mami-ikan-bakar' and status = 'active' and publication_status = 'published' and md5(best_for) = '0a132bc54e3f2b1d2ba77a5c6904c8c8'), md5('Cheap, fresh grilled seafood instead of the touristy Jimbaran beach-BBQ setups, from around 1pm until the day''s catch sells out') = '8a225323d30fa3dae84c5ff457087b0c'),
  (150, 'warung-nasi-ayam-bu-oki', 'why_its_here', (select count(*)::int from venues where slug = 'warung-nasi-ayam-bu-oki' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '2dc2485774132278dbb0ae4193a285d2'), md5('A busy local nasi campur warung opposite Hotel Santika Siligita, in the Nusa Dua and Bualu area. The Balinese mixed-rice plates are cheap and built around chicken.') = '4a264f839ff0b331dc84c61baee5f00f'),
  (151, 'warung-nasi-ayam-bu-oki', 'best_for', (select count(*)::int from venues where slug = 'warung-nasi-ayam-bu-oki' and status = 'active' and publication_status = 'published' and md5(best_for) = 'c4205d5c6982c77411735f0d8734daa7'), md5('A cheap Balinese breakfast or lunch near the resorts, for solo travellers or families, with a spice option') = '5034a4b4e4ed0df4486e868bd714d619'),
  (152, 'warung-nasi-ayam-bu-oki', 'not_for', (select count(*)::int from venues where slug = 'warung-nasi-ayam-bu-oki' and status = 'active' and publication_status = 'published' and md5(not_for) = '4fbb9c1dddfdd15f799083cd6d355d5c'), md5('Anyone avoiding chicken or after a quiet sit-down dinner, because the plates are built around chicken and the warung is a busy breakfast and lunch stop') = '01d5804a986d071e742365cc0d1701ca'),
  (153, 'warung-ramayana-ikan-bakar', 'why_its_here', (select count(*)::int from venues where slug = 'warung-ramayana-ikan-bakar' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '35d6e3bd096b438def2b023dd627a43b'), md5('This beachfront warung on Jimbaran Bay has served Jimbaran-style ikan bakar since around 1990. Fish and seafood are grilled over coconut husks and come with sambal, at tables on the sand facing the sunset.') = '47e408092cde7f506ff3b6c6db3ff83d'),
  (154, 'warung-ramayana-ikan-bakar', 'best_for', (select count(*)::int from venues where slug = 'warung-ramayana-ikan-bakar' and status = 'active' and publication_status = 'published' and md5(best_for) = 'a61906506182fee9529ff36ee7e7a44d'), md5('Picking fresh catch by weight for a casual sunset dinner with your feet near the sand') = '6e16520f1f80e482427651809669ec59'),
  (155, 'westin-nusa-dua-fitness-studio', 'why_its_here', (select count(*)::int from venues where slug = 'westin-nusa-dua-fitness-studio' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '7b75add43899c75ad6001033bf71811b'), md5('The WestinWORKOUT studio at The Westin Resort Nusa Dua is open 24 hours. A rebuilt wellness floor, open since April 2026, adds reformer pilates, spin, a hot yoga sanctuary and a beachfront ice bath. Open-air beach workouts and outdoor HIIT run on the sand.') = '52d4e52ac0efeeaf9430251cc7b8d909'),
  (156, 'westin-nusa-dua-fitness-studio', 'best_for', (select count(*)::int from venues where slug = 'westin-nusa-dua-fitness-studio' and status = 'active' and publication_status = 'published' and md5(best_for) = '1edbb1e247ed68908806eb3ce8d00d97'), md5('People in Nusa Dua who want reformer pilates, spin and ice bath in one place, including non-guests buying a day pass') = 'a7236a6f2108b3254252b20042ba99bf'),
  (157, 'westin-nusa-dua-yoga', 'why_its_here', (select count(*)::int from venues where slug = 'westin-nusa-dua-yoga' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '21fbec45fd8808ad9af88163111f8512'), md5('The Westin Resort Nusa Dua runs yoga from a hot yoga sanctuary added in April 2026, and as group sessions alongside pilates and spin. Ashtanga is on the schedule if you want a harder class.') = '65fd383abd6963d7e32c672d562304ea'),
  (158, 'westin-nusa-dua-yoga', 'best_for', (select count(*)::int from venues where slug = 'westin-nusa-dua-yoga' and status = 'active' and publication_status = 'published' and md5(best_for) = 'b9328fe72b11ddd72ea73e31fdeef1f5'), md5('Guests or day-pass visitors after hot yoga and a demanding Ashtanga class rather than a gentle resort session') = 'fdb1b2f923447e3a1115e2358a6f927e'),
  (159, 'white-orchid-nusa-dua', 'why_its_here', (select count(*)::int from venues where slug = 'white-orchid-nusa-dua' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '523b59ceae44efe8c955bf6a0541bb3d'), md5('A pan-Asian restaurant in the Bali Collection shopping-and-dining complex, in the BTDC resort area of Nusa Dua, open from breakfast through dinner. The menu runs to shareable Asian plates and satay grilled on a Balinese barbecue, and there are outdoor tables.') = '0a75b9db2de1636e1706364302a12a62'),
  (160, 'white-orchid-nusa-dua', 'best_for', (select count(*)::int from venues where slug = 'white-orchid-nusa-dua' and status = 'active' and publication_status = 'published' and md5(best_for) = '30038dbe57b964fb356925add9fdb7f0'), md5('Familiar Asian dishes at lunch or dinner without leaving the enclave, for couples and families in the Nusa Dua resort area') = '776571427b9b09eb59b0205fcd14fb3c')
) as t(n, slug, field, rows_matched, text_ok)
